#!/usr/bin/env bash
set -euo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
S="$root/skills/playbook/SKILL.md"
fail=0
chk() { if eval "$1" >/dev/null 2>&1; then echo "PASS: $2"; else echo "FAIL: $2"; fail=1; fi; }

chk "! grep -q '\.playbook/' '$S'" "no .playbook/ paths"
chk "! grep -q 'playbook_anchor_init\\|playbook_ledger_append\\|playbook_anchor_read' '$S'" "no removed helpers"
chk "! grep -q 'anchor-format' '$S'" "no anchor-format.md cross-references"
chk "! grep -qi 'uncertaint' '$S'" "no uncertainty word anywhere (concept, hook name, ledger)"
chk "! grep -qiE 'append-only( unease)? ledger|unease ledger|the ledger|band-slug|callout shape' '$S'" "ledger mechanism gone"
chk "! grep -qiE 'the anchor file|pinned anchor file|re-?reads? the anchor|into the anchor' '$S'" "no anchor-file references"
chk "! grep -qE '(^|[^-])design\\.md' '$S'" "no bare lowercase design.md vestige"
chk "! grep -q 'DESIGN\\.md' '$S'" "no stale DESIGN.md reference (docs split)"
chk "! grep -q 'playbook-window' '$S'" "no agent-declared window instruction"
chk "grep -q 'carry the confirmed North Star and the user' '$S'" "engine: the hooks carry the North Star into every helper (no presence rule)"
chk "! grep -q 'into every dispatch brief as a single labelled line' '$S'" "engine: the presence rule is gone"

chk "! grep -qi 'receives only the prompt you author\\|receives only its own prompt' '$S'" "engine skill drops the false no-overlay workflow claim"
chk "grep -q 'Every workflow agent receives Playbook.s helper block at SubagentStart' '$S'" "engine skill states the helper block reaches workflow agents"
chk "grep -q 'Every workflow agent receives Playbook.s helper block at SubagentStart' '$root/commands/workflow.md'" "workflow command states the helper block reaches workflow agents"
chk "grep -q 'playbook route workflows' '$root/commands/workflow.md'" "workflow command declares its route through the channel"
chk "grep -qi 'degenerate result' '$S'" "engine warns against trusting a degenerate workflow result"

echo "--- routing procedure"
chk "grep -q '^### 1\\. What each mode is for' '$S'" "routing step 1: what each mode is for"
chk "grep -q '^### 2\\. Rank them' '$S'" "routing step 2: rank them"
chk "grep -q '^### 3\\. The price list' '$S'" "routing step 3: the price list"
chk "grep -q 'not colleagues' '$S'" "engine states the subagent price list"
chk "grep -q 'live routing inputs' '$S'" "engine names wall-clock time and context preservation as routing inputs"
chk "grep -q 'Single-thread work: quick fixes and small contained changes' '$S'" "lone-wolf: single-thread work"
chk "grep -q 'the user has approved one worker knowing it may take longer because it is architecturally better' '$S'" "lone-wolf: coupled work with one approved worker"
chk "grep -q 'Repetitive work and exploration across a set of defined changes' '$S' && grep -q 'Not feature development' '$S'" "interns: repetitive work and exploration, not features"
chk "grep -q 'interns ranks first up to about ten units, workflows beyond that' '$S'" "interns: up to about ten units, workflows beyond"
chk "grep -q 'Small to medium feature work split across platforms or specialisms that must keep talking' '$S' && grep -q 'Nothing big' '$S'" "hackathon: small to medium cross-specialism features"
chk "grep -q 'fast project kickoff where time matters more than polish' '$S'" "hackathon: a fast kickoff"
chk "grep -q 'Most medium to large feature development that can be planned up front' '$S' && grep -q 'Not small features' '$S'" "workflows: most medium to large features"
chk "grep -q 'coupled work too big for one context or too slow with one worker, run as a chain of steps' '$S'" "workflows: coupled work as a chain of steps"
chk "grep -q 'Never the primary recommendation for feature development' '$S'" "gsd: never the primary pick for features"
chk "grep -q 'arrive later' '$S'" "gsd: can be adopted part-way"
chk "grep -q 'hackathon needs agent teams and gsd needs GSD, and the overlay says which are present' '$S'" "engine reads availability from the overlay, not by guessing"
chk "! grep -rqi 'shell echo' '$root/skills' '$root/hooks'" "no shell check of the teams flag, which costs a permission prompt"
chk "grep -q 'Never quote a speed multiple you have not measured' '$S'" "engine forbids unmeasured speed multiples"
chk "grep -q 'Size it by the work it adds, never by how small the codebase it lands in is' '$S'" "engine sizes features by the work, not the codebase"
chk "grep -q 'Medium or larger feature work always has at least two viable modes, so it always gets the picker' '$S'" "medium features always get the picker"
chk "grep -q 'never a placeholder before it' '$S' && grep -qF 'After the pick, never before it' '$root/hooks/session-start'" "no placeholder route before the pick"
chk "! grep -q 'never on size\\|spine density\\|dozens or more frozen units' '$S'" "the separability-only tie-breaks are gone"
n_rk=$(awk '/^### 2\. Rank them/{t=1; next} /^### 3\./{t=0} t&&/^[1-5]\. /{n++} END{print n+0}' "$S")
[ "$n_rk" -eq 5 ] && echo "PASS: five numbered ranking questions" || { echo "FAIL: found $n_rk ranking questions, expected 5"; fail=1; }

echo "--- opt-in routing: the picker and the route channel"
chk "grep -q '^## The picker' '$S'" "engine has a picker section"
chk "grep -q 'AskUserQuestion' '$S'" "picker asks in AskUserQuestion"
chk "grep -qF 'Goal: <goal line>' '$S'" "picker question starts with Goal: <goal line>"
chk "grep -qF '(Recommended)' '$S'" "picker marks one option (Recommended)"
chk "grep -q 'Ask only on the main thread' '$S'" "picker is main thread only"
chk "grep -q 'two or more modes are viable' '$S'" "picker asks only when two or more modes are viable"
chk "grep -q 'rank every available mode, best first, each with one line on why it sits in that position' '$S'" "picker ranks every available mode with a reason"
chk "grep -q 'The options are the top four modes in rank order' '$S' && grep -q 'If a fifth mode is available, name it in the question' '$S'" "picker shows the top four and names a fifth"
chk "grep -q 'inherit the chosen mode' '$S'" "helpers inherit the chosen mode"
chk "grep -qF 'Batch any other early questions in too' '$S'" "picker is batched with other early questions"
chk "grep -qF 'playbook route <mode> <reason>' '$S'" "route is declared through the Bash no-op channel"
chk "grep -qF '📚 Playbook session started · building with' '$S'" "the one-line branded route announcement stays"
chk "grep -q 'known weakening of the North Star guard' '$S'" "the one-option route-line-only trade-off is stated"
chk "grep -qF 'playbook goal <mode> <goal line>' '$S'" "offline picker takes the top recommendation with the goal channel"
chk "grep -q 'wait that long for a typed reply' '$S'" "offline picker waits the window first"
chk "grep -qF 'playbook decision' '$S'" "typed decisions go through the decision channel"
chk "grep -qF 'playbook done' '$S'" "engine closes the goal with the done channel"
chk "! grep -qi 'announce, never gate' '$S'" "Announce, never gate is gone"
chk "! grep -qi 'The user never picks a mode' '$S'" "engine no longer says the user never picks a mode"
chk "! grep -qi 'does not gate the user\\|never gate' '$S' '$root/.claude-plugin/plugin.json'" "no gating-free framing in the engine or manifest"
chk "! grep -qi 'Assume ultracode is the baseline\\|ultracode restraint\\|Match the tool to the task, never to the mode' '$S'" "the ultracode baseline and restraint passages are gone"
chk "! grep -qi 'runs best on ultracode' '$S' '$root/hooks/session-start' '$root/hooks/take-a-beat'" "the ultracode nudge is gone everywhere"
chk "! grep -qF 'Announce and proceed' '$S'" "the announce-and-proceed Red Flag is gone"

echo "--- workflows: settle the plan, then the user opts in"
chk "grep -q 'settle the plan with the user' '$S'" "engine settles the plan before a workflow"
chk "grep -qF 'reply \"use ultracode\", typed rather than pasted' '$S'" "engine asks for a typed use ultracode"
chk "grep -q 'From the second, ask them to run .*/effort ultracode' '$S' && grep -q 'switch back to their earlier effort' '$S'" "engine falls back to /effort ultracode with the switch-back warning"
chk "grep -qF 'workflows (awaiting opt-in)' '$S'" "engine names the awaiting status"
chk "grep -q 'take the next-ranked mode and log why' '$S'" "offline cannot opt in, so it takes the next mode"
chk "! grep -qF 'change made' '$S' '$root/commands/workflow.md' '$root/README.md' '$root/hooks/session-start'" "the change-made stop is gone everywhere"
chk "grep -qF 'use ultracode' '$root/commands/workflow.md' && grep -q 'settle the plan' '$root/commands/workflow.md'" "the workflow command carries the same opt-in"
chk "grep -q 'Start the Workflow tool before the plan is settled' '$S'" "Red Flag: no Workflow tool before the plan and the opt-in"

echo "--- oversight: online, or a judge in the background"
chk "grep -q 'Batch with it a second question starting .Oversight:' '$S'" "engine batches the oversight question into the picker"
chk "grep -qF \"\\\`You'll oversee\\\`: You review progress and decisions yourself.\" '$S' && grep -qF '\`Defer to a judge after 10 mins waiting\`: The model will ask you' '$S' && grep -qF '\`Defer to a judge after 30 mins waiting\`' '$S' && grep -qF '\`Autonomous development\`: The model will refer any decisions or blockers to a judge without alerting you.' '$S'" "engine names the four oversight options with their descriptions"
chk "grep -q 'no question is shown, so an open dialog never blocks the run' '$S'" "engine: no blocking dialog while a judge oversees"
chk "grep -qF 'Oversight:' '$root/hooks/session-start' && grep -qF 'Autonomous development' '$root/hooks/session-start' && grep -qF 'Defer to a judge after 30 mins waiting' '$root/hooks/session-start'" "overlay carries the oversight question"
chk "grep -q 'ask for .\/effort ultracode. instead of \"use ultracode\"' '$S' && grep -q 'ask the user to run .\/effort ultracode. before they go' '$root/skills/offline-mode/SKILL.md'" "a judge overseeing asks for /effort ultracode, not the typed word"
chk "grep -qF 'giving every agent() call a model' '$root/hooks/session-start' && grep -q 'reviewers and verifiers included' '$S' && grep -q 'reviewers and verifiers included' '$root/commands/workflow.md'" "workflow scripts give every agent() call a model"
chk "! grep -q 'askUserQuestionTimeout' '$root/skills/setup/SKILL.md' '$root/README.md'" "setup never offers Claude Code's question timeout"
chk "grep -q 'Autonomous development' '$root/README.md'" "README describes oversight"
chk "grep -q 'Oversight:. question, and its answer turns offline behaviour on or off' '$root/skills/offline-mode/SKILL.md'" "offline-mode explains the oversight answer"

echo "--- the user's decisions win"
chk "grep -qF \"outrank you and every helper, reviewer, judge and reviser\" '$S'" "engine: decisions outrank every helper, reviewer, judge and reviser"
chk "grep -q 'never credit the user with a rule they did not state' '$S'" "engine: never credit the user with an unstated rule"
chk "grep -q 'A conflict with one is a question for the user, never a change' '$S'" "engine: a conflict is a question"
chk "grep -q 'show the evidence and let them re-decide' '$S'" "engine: an unsafe decision is re-decided by the user, never weakened quietly"
chk "grep -qi 'outrank' '$root/skills/review-panel/SKILL.md'" "review-panel: decisions outrank the reviewers"
chk "grep -qi 'outrank' '$root/commands/workflow.md'" "workflow command: decisions outrank the reviewers"

echo "--- the five review lines, verbatim"
R1="Review against the user's spec and decisions, with one reviewer unless the user asks for more."
R2="A finding blocks only if it is a bug whatever the user's appetite for risk. List the rest, and weigh every fix against its cost."
R3="Reviewers and revisers never change scope or a decision; a conflict is a question for the user."
R4="Only a bug earns another round. If two rounds still find bugs, stop reviewing and take a beat: simplify, accept a contained risk, or ask. Anything bigger than a fix needs a serious assessment and sign-off from a judge or the user; on money or security code, ask."
R5="Growth past what the user agreed is bad news: say it in numbers, with the smaller option."
for f in skills/playbook/SKILL.md skills/review-panel/SKILL.md commands/workflow.md; do
  i=1
  for line in "$R1" "$R2" "$R3" "$R4" "$R5"; do
    chk "grep -qF \"$line\" '$root/$f'" "$f carries review line $i"
    i=$((i+1))
  done
done
chk "grep -q 'holds the third round' '$S'" "engine: the third round is held by the guard"
chk "grep -q 'holds the third round' '$root/skills/review-panel/SKILL.md'" "review-panel: the third round is held by the guard"
chk "grep -q 'holds the third round' '$root/commands/workflow.md'" "workflow command: the third round is held by the guard"
chk "grep -q 'one reviewer unless the user asks for more' '$root/skills/review-panel/SKILL.md'" "review-panel: one reviewer unless the user asks for more"

echo "--- unease is a score"
chk "grep -q '^## Unease' '$S'" "engine has an Unease section"
chk "grep -qF 'playbook unease <uneasy|concerned|alarmed> <reason>' '$S'" "engine: the model adds to the score through the channel"
chk "grep -qF 'playbook rethink' '$S'" "engine: uneasy means a rethink, through the channel"
chk "grep -qE '\\*\\*Uneasy:\\*\\* stop and rethink' '$S'" "score level uneasy: rethink"
chk "grep -qE '\\*\\*Concerned:\\*\\* consult a judge' '$S'" "score level concerned: consult a judge"
chk "grep -qE '\\*\\*Alarmed:\\*\\* consult a judge, or ask the user if they.re here' '$S'" "score level alarmed: a judge, or the user if they're here"
chk "grep -q 'hold the main thread.s new edits and dispatches; judges and read-only lookups still go through' '$S'" "engine: unanswered levels hold edits and dispatches"
chk "grep -q 'Offline: push, wait the window, then an outside judge' '$S'" "score level alarmed offline: push, wait, judge"
chk "grep -q 'description starts \`judge:\`' '$S'" "a judge is an Agent call whose description starts judge:"
chk "grep -q 'codex:codex-rescue' '$S'" "Codex rescue counts as a judge"
chk "grep -q 'evidence, not proof' '$S'" "the score is evidence for a stop, not proof of success"
chk "! grep -rqE 'faintly_uneasy|near_breaking' '$root/skills' '$root/commands' '$root/README.md'" "the eleven-level register is gone from skills, commands and README"

echo "--- interns lanes (C)"
chk "grep -q 'unnamed background' '$S'" "interns: unnamed background helpers"
chk "grep -q 'reports once' '$S'" "interns: each reports once"
chk "grep -qi 'one review at the end' '$S'" "interns: one review at the end"
chk "grep -q 'owns its files' '$S'" "interns: a lane owns its files"
chk "grep -q 'takes no lane and runs no long foreground work while lanes run' '$S'" "interns: the main thread stays free for reports"
chk "grep -q 'runs its workers in the foreground' '$S'" "interns: a joint-lead runs its workers in the foreground"
chk "grep -q 'agentId' '$S' && grep -q 'SendMessage' '$S'" "interns: follow-ups go to the agentId with SendMessage"
chk "grep -q 'named dispatch or a team outside hackathon is refused' '$S'" "interns: a named dispatch outside hackathon is refused"

echo "--- hackathon skill (C, A and B)"
H="$root/skills/hackathon-team/SKILL.md"
chk "grep -q 'small crew of specialists' '$H'" "hackathon: a small crew of specialists"
chk "grep -q 'like a few friends at a hackathon' '$H'" "hackathon: the user's own picture"
chk "grep -q 'The lead.* talks to the user' '$H'" "hackathon: the lead talks to the user"
chk "grep -q 'builds too' '$H'" "hackathon: the lead builds too"
chk "grep -q 'not a hub: it never collects proposals to reconcile them itself' '$H'" "hackathon: the lead is not a hub"
chk "grep -q 'Talk directly to the colleague a question or change concerns, never through the lead' '$H'" "hackathon: teammates talk to each other directly"
chk "awk '/^\`\`\`\$/{n++} n==1' '$H' | grep -q 'The crew: <name>' && awk '/^\`\`\`\$/{n++} n==1' '$H' | grep -q 'owned by <owner>'" "hackathon: every brief names the crew and the interface owner"
chk "grep -q 'Run long commands in the background' '$H'" "hackathon: long commands go to the background"
chk "grep -qF '\`playbook publish <what changed>\` copies the draft over the interface and calls the regroup' '$H' && grep -qF 'REGROUP: <what changed and why>' '$H'" "hackathon: publishing a change calls a regroup, announced once by message"
chk "grep -q 'nobody edits the interface itself' '$H' && grep -q 'keep no version line in the file' '$H'" "hackathon: changes are drafted, and Playbook numbers the versions"
chk "awk '/^\`\`\`\$/{n++} n==1' '$H' | grep -q 'Never edit it directly: make a change in <draft path>'" "hackathon: every brief says to draft and publish"
chk "grep -q 'the hold lifts and every crew member is told at its next step' '$H'" "hackathon: everyone is told when a regroup closes"
chk "grep -qF 'playbook publish <what changed>' '$root/README.md'" "README: the interface is changed by publishing a draft"
chk "grep -q \"Every crew member's edits are held, the lead's included\" '$H'" "hackathon: a regroup holds every crew member, the lead included"
chk "grep -q 'puts the agreed version in the draft and publishes it, once' '$H'" "hackathon: the owner publishes the agreed version once"
chk "grep -q 'messages every colleague once, the lead included' '$H'" "hackathon: the regroup call reaches the lead too"
chk "grep -q 'through the shell as much as the Edit tool' '$H'" "hackathon: the hold covers shell edits"
chk "grep -qF 'playbook aligned <name>' '$H' && grep -q 'accepts it only from someone who has read the current version' '$H'" "hackathon: approval only after reading the latest version"
chk "grep -qF 'RESUME: interface v<n> aligned' '$H'" "hackathon: the last approval sends RESUME"
chk "grep -qF 'playbook resume <reason>' '$H'" "hackathon: the lead's way out of a stuck regroup"
chk "! grep -q 'BLOCKING' '$H' && ! grep -q 'adopted' '$H'" "hackathon: the old BLOCKING and adopted protocol is gone"
chk "grep -qF 'playbook interface [<name>]' '$H'" "hackathon: the lead declares the interface"
chk "grep -q 'Playbook keeps it in its own storage, outside the project, so it never lands in the user' '$H'" "hackathon: the interface is kept outside the project"
chk "grep -qF 'Write the interface into the project; Playbook keeps it outside the repository.' '$H'" "hackathon: never write the interface into the project"
chk "grep -qF 'kept by Playbook outside your project, never in your repository' '$root/README.md'" "README: the interface is kept outside the project"
chk "! grep -q 'blocks a stale teammate' '$H'" "hackathon: the old per-edit stale-read block is gone"
chk "grep -q 'do their own reading and do not spawn helpers' '$H'" "hackathon: teammates read for themselves and spawn no helpers"
chk "grep -q 'small to medium feature work split across platforms or specialisms that must keep talking' '$H'" "hackathon: recommended for small to medium cross-specialism features"
chk "grep -q 'Mailboxes are slow' '$H' && grep -q 'never acknowledge an acknowledgement' '$H'" "hackathon: message cadence keeps mailboxes clear"
chk "grep -q 'The lead takes the smallest part' '$H'" "hackathon: the lead stays free to answer"
chk "grep -qF 'playbook part-done <name>' '$H'" "hackathon A: the part-done declaration"
chk "grep -q 'declared only when no regroup is open and colleagues no longer need the teammate' '$H'" "hackathon A: part-done only outside a regroup, once colleagues no longer need it"
chk "grep -q \"At its next idle the hook stops the teammate's work\" '$H' && grep -q 'the lead shuts it down once its part is integrated' '$H'" "hackathon A: a part-done teammate's work is stopped and the lead shuts it down"
chk "grep -q '## Message priorities' '$H' && grep -q 'One tag per message' '$H'" "hackathon: message priorities, one tag per message"
for t in SOON ASAP URGENT REGROUP RESUME; do chk "grep -q \"^| \\\`\${t}:\\\`\" '$H'" "hackathon: the priorities table has ${t}"; done
chk "grep -qF \"Read <sender>'s message before your next piece of work.\" '$H' && grep -qF \"Stop as soon as you reasonably can and read <sender>'s message.\" '$H'" "hackathon: SOON and ASAP nudges quoted as sent"
chk "grep -q 'The lead is never force-stopped' '$H' && grep -q 'within 10 minutes arrives as ASAP' '$H'" "hackathon: the lead's exemption and the URGENT cap"
chk "awk '/^\\\`\\\`\\\`\$/{n++} n==1' '$H' | grep -q 'A message reaches you' && awk '/^\\\`\\\`\\\`\$/{n++} n==1' '$H' | grep -q '\"URGENT:\"'" "hackathon: the template says when a message arrives and carries the tags"
chk "grep -q 'fresh teammate' '$H'" "hackathon A: a follow-up needs a fresh teammate"
chk "grep -qF 'playbook waiting <name> on <colleague> <what>' '$H'" "hackathon B: the waiting declaration"
chk "grep -q 'at most three pushes in a row' '$H'" "hackathon B: pushes are capped at three in a row"
chk "grep -q 'resets the count' '$H'" "hackathon B: a declaration or a message resets the count"
chk "grep -q 'Brief template for each teammate' '$H'" "hackathon: a brief template for each teammate"
chk "awk '/^\`\`\`\$/{n++} n==1' '$H' | grep -qF 'playbook waiting <name> on <colleague> <what>'" "hackathon: the template carries the waiting command"
chk "awk '/^\`\`\`\$/{n++} n==1' '$H' | grep -qF 'playbook part-done <name>'" "hackathon: the template carries the part-done command"
chk "awk '/^\`\`\`\$/{n++} n==1' '$H' | grep -qF 'playbook aligned <name>' && awk '/^\`\`\`\$/{n++} n==1' '$H' | grep -q 'REGROUP'" "hackathon: the template carries the regroup"
chk "! grep -qi 'joint-leads -> workers fan-out.*belongs to the' '$H'" "hackathon: the contradicting joint-leads text is gone"
chk "! grep -qi 'Peer goes idle, notifies the lead' '$H'" "hackathon: the old idle-notifies-lead loop is gone"
chk "! grep -q 'cross-communicating crew of expert' '$H'" "hackathon: the old crew definition is gone"

echo "--- model rule"
M="$root/skills/model-rule/SKILL.md"
chk "! grep -qi 'with a reviewer above' '$M'" "model-rule: profile 2 no longer needs a reviewer above"
chk "! grep -qi 'check of last resort\\|never downgrade' '$M'" "model-rule: profile 3 has no check of last resort or never-downgrade"
chk "grep -q 'No agent exists only to watch another' '$M'" "model-rule: no agent exists only to watch another"
chk "grep -q 'Sonnet builds and checks' '$M' && grep -q 'Opus plans and judges' '$M'" "model-rule: Sonnet builds and checks, Opus plans and judges"
chk "grep -q 'Sonnet builds and checks, Opus plans and judges' '$S'" "engine states the model rule"
chk "grep -q 're-deriving an answer to defeat correlated error, never reviewing your own build' '$S'" "engine narrows independent verification"
chk "grep -q 'natural finish above about 200k' '$S'" "engine: fresh sessions at a natural finish above 200k"

echo "--- the time rule is gone"
chk "[ ! -e '$root/skills/time-rule' ]" "skills/time-rule is deleted"
chk "! grep -rqiE 'time-rule|time rule|divide by ten|divide the estimate' '$root/skills' '$root/commands' '$root/README.md' '$root/hooks' '$root/.claude-plugin'" "no time-rule reference in skills, commands, README, hooks or manifests"

echo "--- removed doctrine stays removed"
chk "! grep -rqF '🪙 **Playbook**' '$root/skills' '$root/commands' '$root/README.md' '$root/hooks'" "no 🪙 downshift marker: the dispatch line shows each dispatch's model"
chk "grep -qF 'Print no model marker of your own' '$root/skills/model-rule/SKILL.md'" "model rule: the dispatch guard's line replaces any marker"
chk "! grep -rqiE 'escalation ladder|unease sense|degrade the North Star below|playbook_anchor_block|re-anchor after compaction restores' '$root/skills' '$root/commands' '$root/README.md'" "no escalation ladder, unease sense, old override wording or deleted anchor in the doctrine"
chk "! grep -qF 'generate, then independently check' '$root/README.md'" "README: independent verification is re-deriving, not reviewing your own build"

echo "--- tenets"
chk "grep -q 'The nine tenets, always live:' '$S'" "engine carries the nine-tenet header"
n_s=$(awk '/The nine tenets, always live:/{t=1; next} t&&/^[1-9]\. /{n++} t&&/^$/{exit} END{print n+0}' "$S" 2>/dev/null)
[ "$n_s" -eq 9 ] \
  && echo "PASS: nine tenets in engine skill" \
  || { echo "FAIL: found $n_s tenets in the engine skill tenets block, expected 9"; fail=1; }
chk "grep -q '^1\\. Remember what matters: the goal the user confirmed and their decisions; the hooks carry both\\.' '$S'" "tenet 1 rewritten"
chk "grep -q '^2\\. Ask early, in one batch, the mode pick included, and again whenever a choice is the user.s\\.' '$S'" "tenet 2 rewritten"
chk "grep -q '^3\\. Peers argue on reasoning, not rank; nobody outranks the user.s decisions\\.' '$S'" "tenet 3 rewritten"
chk "grep -q '^4\\. Unease is scored from evidence: rethink, then a judge, then the user\\.' '$S'" "tenet 4 rewritten"
chk "grep -q '^5\\. Offline behaviour is enabled only by the offline-mode skill' '$S'" "tenet 5 shortened, kept"
